// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));

        uint256 before = c.tokenBalance(actor);
        vm.assume(before == 0);

        Supporter sup = new Supporter();
        address supporterAddr = address(sup);

        uint256 balBefore = c.tokenBalance(supporterAddr);
        vm.assume(balBefore == 0);

        vm.prank(supporterAddr);
        bool ok;
        try c.airDrop() {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(c.tokenBalance(supporterAddr) == 20);
        } else {
            assertTrue(c.tokenBalance(supporterAddr) == 0);
        }
    }
}

contract Supporter {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}
